18544:     function solveBattle(initialState,maxAttack) {
18545:       const memo = new Map();
18546:       function dfs(state,remaining) {
18547:         const key = battleStateKey(state) + '#' + remaining;
18548:         if (memo.has(key)) return memo.get(key);
18549:         const aliveBefore = countBattleAlive(state);
18550:         let best = {killed:0,cost:0,order:[]};
18551:         if (aliveBefore === 0) {
18552:           memo.set(key,best);
18553:           return best;
18554:         }
18555:         for (let position=0;position<BATTLE_SIZE;position++) {
18556:           const enemy = state[position];
18557:           if (!enemy || !enemy.alive || enemy.hp <= 0 || enemy.hp > remaining) continue;
18558:           const result = battleAttack(state,position);
18559:           if (!result) continue;
18560:           const killedNow = aliveBefore - countBattleAlive(result.state);
18561:           const rest = dfs(result.state,remaining - result.cost);
18562:           const candidate = {killed:killedNow + rest.killed,cost:result.cost + rest.cost,order:[position].concat(rest.order)};
18563:           if (betterBattleSolution(candidate,best)) best = candidate;
18564:         }
18565:         memo.set(key,best);
18566:         return best;
18567:       }
18568:       return dfs(initialState,maxAttack);
18569:     }
