3132:   function normalizePitChance(value) {
3133:     const result = number(value);
3134:     if (result === null) return null;
3135:     const normalized = result > 1 && result <= 100 ? result / 100 : result;
3136:     return normalized >= 0 && normalized <= 1 ? normalized : null;
