3139:   function pitAtLeastWins(chances, needed) {
3140:     let distribution = [1];
3141:     for (const chance of chances) {
3142:       const next = Array(distribution.length + 1).fill(0);
3143:       distribution.forEach((value, wins) => { next[wins] += value * (1 - chance); next[wins + 1] += value * chance; });
3144:       distribution = next;
3145:     }
3146:     return distribution.slice(needed).reduce((sum,value)=>sum+value,0);
3147:   }
